async function addAna(){const ttl=$('#at').value.trim();if(!ttl)return;const notes=[...document.querySelectorAll('.anc')].map(x=>x.value.trim()).filter(Boolean),imgs=(await Promise.all([...($('#aimg').files||[])].map(rd))).filter(Boolean);LGD.ana.push({id:uid(),d:$('#ad').value||tdy(),ttl,sess:$('#as').value,bias:$('#ab').value,lv:$('#al').value,plan:$('#ap').value,inv:$('#ai').value,notes,imgs,fb:'',sc:'',ok:false});lgsv('ana');LG.adding=false;render()}
