function sheetsH(a){const L=sheetList(a),s=sheetSel(a),d=s&&sheetData(s),cus=s&&s.cus;
return`<div class="card"><h3>Tài liệu (Sheet)<span class="hr"><button class="bt" data-sh="${a}|new">+ Tạo sheet</button></span></h3>${SH.add?`<div class="fm" style="grid-template-columns:1fr auto"><input id="shn" placeholder="Tên sheet"><button class="bt" data-sh="${a}|create">Tạo</button></div>`:''}<div class="seg wk" style="margin:12px 0">${L.map(x=>`<button class="${s&&x.id==s.id?'on':''}" data-sh="${a}|sel|${x.id}">${esc(x.n)}</button>`).join('')}</div>${s?`${cus?`<div class="fm" style="grid-template-columns:1fr auto"><input data-shn="1" value="${esc(s.n)}" aria-label="Tên sheet"><button class="x" data-sh="${a}|dsheet">Xoá sheet</button></div>`:'<p class="nt" style="margin:0">Sheet hệ thống: sửa ô thì dữ liệu hiển thị trong ứng dụng đổi theo.</p>'}<div class="shw"><table class="sht"><thead><tr><th class="rn">#</th>${d.cols.map((c,i)=>`<th>${cus?`<input data-shc="${i}" value="${esc(c.n)}"><button class="x" data-sh="${a}|dcol|${i}">×</button>`:esc(c.n)}</th>`).join('')}<th></th></tr></thead><tbody>${d.rows.map((r,ri)=>`<tr><td class="rn">${ri+1}</td>${d.cols.map((c,ci)=>`<td>${cellH(c,r[ci],ri,ci)}</td>`).join('')}<td><button class="x" data-sh="${a}|drow|${ri}">Xoá</button></td></tr>`).join('')}</tbody></table></div><div class="pf"><button class="bt" data-sh="${a}|arow">+ Thêm dòng</button>${cus?`<button class="ii" data-sh="${a}|acol">+ Thêm cột</button>`:''}</div>${cus&&SH.ncol?`<div class="fm" style="grid-template-columns:1fr auto"><input id="shcn" placeholder="Tên cột mới"><button class="bt" data-sh="${a}|addcol">Thêm cột</button></div>`:''}`:'<p class="nt">Chưa có sheet nào.</p>'}</div>`}
const shOn=a=>cur==a&&(a=='legd'?LG.tab=='doc':AT[a]=='doc');
$('#main').addEventListener('click',ev=>{const t=ev.target.closest('[data-sh]');if(!t)return;const q=t.dataset.sh.split('|'),a=q[0],b=q[1],c=q[2];if(!shOn(a))return;const s=sheetSel(a);
if(b=='new')SH.add=!SH.add;
else if(b=='create'){const n=$('#shn').value.trim();if(!n)return;const id=uid();SHEETS.push({id,area:a,name:n,cols:[{n:'Cột 1'},{n:'Cột 2'},{n:'Cột 3'}],rows:[['','','']]});SV('ls-sheets',SHEETS);SH.sel[a]='c:'+id;SH.add=false}
else if(b=='sel')SH.sel[a]=c;
else if(b=='arow'){const d=sheetData(s),r=d.cols.map(x=>isT(x)?nowDT():x.t=='date'?tdy():x.t=='num'||x.t=='dec'?0:x.t=='sel'?((typeof x.o=='function'?x.o():x.o)[0]||''):'');sheetSave(s,[...d.rows,r])}
else if(b=='drow')sheetSave(s,sheetData(s).rows.filter((_,i)=>i!=+c));
else if(b=='acol')SH.ncol=!SH.ncol;
else if(b=='addcol'){const n=$('#shcn').value.trim();if(!n||!s.cus)return;s.cus.cols.push({n});s.cus.rows.forEach(r=>r.push(''));SV('ls-sheets',SHEETS);SH.ncol=false}
else if(b=='dcol'){if(!s.cus||s.cus.cols.length<2)return;s.cus.cols.splice(+c,1);s.cus.rows.forEach(r=>r.splice(+c,1));SV('ls-sheets',SHEETS)}
else if(b=='dsheet'){if(!s.cus)return;SHEETS.splice(SHEETS.indexOf(s.cus),1);SV('ls-sheets',SHEETS);SH.sel[a]=null}
render()});
$('#main').addEventListener('change',ev=>{const t=ev.target;if(!shOn(cur))return;const s=sheetSel(cur);if(!s)return;
if(t.dataset.sc!=null){const q=t.dataset.sc.split(':'),d=sheetData(s),c=d.cols[+q[1]];let v=t.value;if(c.t=='num')v=num(v)||0;else if(c.t=='dec')v=pF(v);const rows=d.rows.map(r=>r.slice());rows[+q[0]][+q[1]]=v;sheetSave(s,rows);render()}
else if(t.dataset.shc!=null&&s.cus){s.cus.cols[+t.dataset.shc].n=t.value;SV('ls-sheets',SHEETS);render()}
else if(t.dataset.shn!=null&&s.cus){s.cus.name=t.value;SV('ls-sheets',SHEETS);render()}});
function render(){
CH.forEach(c=>c.destroy());CH=[];
const p=PG[cur],[s,e]=rng(),D=Chart.defaults,hr=new Date().getHours();
D.font.family='Manrope,sans-serif';D.color=cv('mut');D.animation=RM?false:{duration:900,easing:'easeOutQuart'};
Object.assign(D.plugins.tooltip,{backgroundColor:cv('card'),titleColor:cv('ink'),bodyColor:cv('mut'),borderColor:cv('line'),borderWidth:1,padding:12,boxPadding:5,cornerRadius:10});
D.plugins.legend.labels.usePointStyle=true;
const title=cur=='stats'?(hr<11?'Chào buổi sáng':hr<18?'Chào buổi chiều':'Chào buổi tối'):p.n;
let h=`<header><h1>${title}</h1><p>${p.d}</p></header>`;
if(cur=='today'){h+=todayHtml()}else if(cur=='goal'){h+=goalHtml()}else if(cur=='cal'){h+=calHtml()}else if(cur=='sys'){h+=sysHtml()}else if(cur=='acc'){const tot=ACC.reduce((a,x)=>a+x[2],0);
h+=`<div class="g" style="margin-top:26px"><div class="card s2"><h3>Số dư các tài khoản</h3><div class="tot"><b data-v="${tot}" data-d="1">0</b><i>tr đ</i></div>${ACC.map(a=>`<div class="row"><div><b>${a[0]}</b><span>${a[1]}</span></div><div class="bar"><u style="width:${a[2]/tot*100}%"></u></div><em>${nf(a[2],1)} tr</em></div>`).join('')}</div>
<div class="card"><h3>Kết nối Google Sheet</h3>${['LEGD','Business','English','PageFly','Cá nhân','Tài chính'].map(n=>`<div class="row r2"><div><b>${n}</b><span>Tab “${n}”</span></div><span class="pill">Dữ liệu mẫu</span></div>`).join('')}<p class="nt">Mỗi mảng đọc từ một tab riêng. Hiện đang hiển thị dữ liệu mẫu.</p></div></div>`}
else{
const seg=[['7','7 ngày'],['30','30 ngày'],['90','90 ngày'],['d','Ngày'],['wk','Tuần'],['mo','Tháng'],['rg','Tuỳ chọn']],len=e-s+1;
const ex=F.m=='d'?`<input type="date" data-f="d" value="${F.d}" min="${iso(dates[0])}" max="${iso(dates[N-1])}">`:F.m=='wk'?`<select data-f="wk" aria-label="Chọn tuần">${WK.map((w,i)=>`<option value="${i}" ${i==F.wk?'selected':''}>${w.l}</option>`).join('')}</select>`:F.m=='mo'?`<select data-f="mo" aria-label="Chọn tháng">${MO.map((w,i)=>`<option value="${i}" ${i==F.mo?'selected':''}>${w.l}</option>`).join('')}</select>`:F.m=='rg'?`<input type="date" data-f="a" value="${F.a}" min="${iso(dates[0])}" max="${iso(dates[N-1])}"><input type="date" data-f="b" value="${F.b}" min="${iso(dates[0])}" max="${iso(dates[N-1])}">`:'';
h+=`<div class="fb"><div class="seg">${seg.map(([m,l])=>`<button data-m="${m}" class="${F.m==m?'on':''}">${l}</button>`).join('')}</div>${ex}<span class="rt">${fd(dates[s])} – ${fd(dates[e])}/${dates[e].getFullYear()} · ${len} ngày${len>45?' · gộp theo tuần':''}</span></div>`;
h+=CUSTOM[cur]?CUSTOM[cur]():`<div class="k">${p.k.map(k=>kpi(k,s,e)).join('')}${p.x?p.x(s,e):''}</div><div class="g">${p.c.map((c,i)=>`<div class="card ${c.s==2?'s2':c.s==3?'s3':''}"><h3>${c.h}</h3>${c.t=='heat'?`<div class="hm">${heat(s,e)}</div>`:`<div class="cv"><canvas id="c${i}"></canvas></div>`}</div>`).join('')}</div>`}
if(AREA[cur])h+=docH(cur);$('#main').innerHTML=h;cu();if(cur=='goal')goalAfter();if(cur=='fin')finAfter();if(cur=='legd'&&LG.tab=='res'&&LG.view=='chart'&&document.getElementById('tc'))CH.push(tradeChart());
if(!['acc','cal','sys','today','goal','fin','legd','biz','eng','pf','per'].includes(cur))p.c.forEach((c,i)=>{if(c.t!='heat')CH.push(chart('c'+i,c,s,e))})}
$('#nav').innerHTML=Object.keys(PG).map(k=>`<button class="nv ${k==cur?'on':''}" data-p="${k}" title="${PG[k].n}"><svg viewBox="0 0 24 24">${I[k]}</svg><span>${PG[k].n}</span></button>`).join('');
$('#nav').onclick=ev=>{const b=ev.target.closest('[data-p]');if(!b)return;cur=b.dataset.p;document.querySelectorAll('.nv').forEach(n=>n.classList.toggle('on',n==b));scrollTo(0,0);render()};
$('#main').onclick=ev=>{const b=ev.target.closest('[data-m]');if(b){F.m=b.dataset.m;render()}};
$('#main').onchange=ev=>{const f=ev.target.dataset.f;if(!f||!ev.target.value)return;F[f]=f=='a'||f=='b'||f=='d'?ev.target.value:+ev.target.value;render()};
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(()=>render());else render();
